<?php
require_once __DIR__.'/config/database.php'; require_once __DIR__.'/includes/functions.php'; require_role(['admin','staff']); verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){
 $bid=(int)($_POST['bill_id']??0);$amount=round((float)($_POST['amount']??0),2);$method=$_POST['method']??'cash';$reference=trim($_POST['reference']??'');$date=$_POST['payment_date']??date('Y-m-d');
 $pdo->beginTransaction();
 try{$s=$pdo->prepare("SELECT b.*,c.full_name FROM bills b JOIN customers c ON c.id=b.customer_id WHERE b.id=? FOR UPDATE");$s->execute([$bid]);$b=$s->fetch();
 if(!$b||$amount<=0||$amount>(float)$b['balance']+0.001)throw new RuntimeException('Payment must be greater than zero and cannot exceed the bill balance.');
 $s=$pdo->prepare("INSERT INTO payments(bill_id,customer_id,amount,method,reference,payment_date,recorded_by) VALUES(?,?,?,?,?,?,?)");$s->execute([$bid,$b['customer_id'],$amount,$method,$reference?:null,$date,current_user()['id']]);
 $pdo->prepare("UPDATE bills SET balance=GREATEST(balance-?,0) WHERE id=?")->execute([$amount,$bid]);
 $u=$pdo->prepare("SELECT id FROM users WHERE customer_id=?");$u->execute([$b['customer_id']]);$uid=$u->fetchColumn();if($uid)add_notification($pdo,(int)$uid,"Payment of ".money($amount)." received for bill {$b['bill_number']}.");
 audit($pdo,'RECORD PAYMENT',"Bill {$b['bill_number']}: ".money($amount));$pdo->commit();flash('success','Payment recorded successfully.');
 }catch(Throwable $e){$pdo->rollBack();flash('error',$e instanceof RuntimeException?$e->getMessage():'Could not record payment.');}
 redirect('payments.php');
}
$bills=$pdo->query("SELECT b.id,b.bill_number,b.balance,c.full_name,c.account_number FROM bills b JOIN customers c ON c.id=b.customer_id WHERE b.balance>0 ORDER BY b.due_date")->fetchAll();
$rows=$pdo->query("SELECT p.*,c.full_name,b.bill_number FROM payments p JOIN customers c ON c.id=p.customer_id JOIN bills b ON b.id=p.bill_id ORDER BY p.created_at DESC")->fetchAll();$pageTitle='Payment management';require 'includes/header.php';
?>
<div class="two-col"><div class="panel"><div class="panel-head"><h3>Record a payment</h3></div><form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Outstanding bill *</label><select name="bill_id" id="bill-select" required><option value="">Select bill</option><?php foreach($bills as $b):?><option value="<?=$b['id']?>" data-balance="<?=$b['balance']?>"><?=e($b['bill_number'].' · '.$b['full_name'].' · balance '.money($b['balance']))?></option><?php endforeach;?></select><label>Amount received (KES) *</label><input type="number" name="amount" min="0.01" step="0.01" required><label>Payment method</label><select name="method"><option value="cash">Cash</option><option value="bank">Bank transfer</option><option value="other">Other / manual reference</option></select><label>Receipt / reference number</label><input name="reference" placeholder="Optional reference"><label>Payment date</label><input type="date" name="payment_date" value="<?=date('Y-m-d')?>" required><button class="btn primary" <?=$bills?'':'disabled'?>>Save payment</button><p class="hint">This module records payments manually. It does not connect to mobile money or a bank.</p></form></div><div class="panel"><h3>Payment controls</h3><ul class="feature-list"><li>Payments must be greater than zero.</li><li>A payment cannot exceed the outstanding bill balance.</li><li>Bill balances update automatically.</li><li>Payment confirmations appear in customer notifications.</li><li>Every payment is linked to a bill and customer.</li></ul></div></div>
<div class="panel"><div class="panel-head"><h3>Payment history</h3><input class="search-input" data-table-search="payments-table" placeholder="Search payments..."></div><div class="table-wrap"><table id="payments-table"><thead><tr><th>Receipt</th><th>Customer</th><th>Bill</th><th>Amount</th><th>Method</th><th>Reference</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>PAY-<?=str_pad((string)$r['id'],6,'0',STR_PAD_LEFT)?></td><td><?=e($r['full_name'])?></td><td><?=e($r['bill_number'])?></td><td><?=money($r['amount'])?></td><td><?=e(ucfirst($r['method']))?></td><td><?=e($r['reference']??'—')?></td><td><?=e($r['payment_date'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="empty">No payments recorded.</td></tr><?php endif;?></tbody></table></div></div>
<?php require 'includes/footer.php';?>
